// Public test fixture bridge: executes C generated by recomp/android_fixture.py
// from a three-instruction, author-created PowerPC ELF (return 42).
// This file must be compiled by clang-cl, not MSVC; the recomp uses Clang
// builtins and may require the musttail attribute for real functions.
#include "funcs.h"
#include <stdlib.h>

int g_ppc_trace = 0;
volatile int g_core_preempt[3] = {0};

void ppc_trace_enter(uint32_t address) { (void)address; }
void ppc_preempt(Cpu* cpu) { (void)cpu; }
void ppc_unimplemented(Cpu* cpu, uint32_t address, uint32_t opcode) {
    (void)cpu; (void)address; (void)opcode;
    abort();
}

// Exposes only a simple C ABI to the UWP C++/CX application, which remains
// compiled by MSVC. All PowerPC/generated source is in the clang-built lib.
int nsmbu_fixture_return_42(void) {
    Cpu cpu = {0};
    cpu.core = 0;
    f_02000000(&cpu);
    return (int)cpu.r[3];
}
